        // 看起来和它不是一套。代价是位置最多偏半像素，看不出来。
        const left = Math.round(box.left - hostRect.left - layer.host.clientLeft + layer.host.scrollLeft);
        const top = Math.round(box.top - hostRect.top - layer.host.clientTop + layer.host.scrollTop);
